import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay settings on the defaults mode="fast" and level="3".

    keys[i] is set to values[i]. Returns the resulting values: first the
    value of "mode", then the value of "level", then the values of any
    other keys in the order they first appear in `keys`. If a key appears
    more than once, the last value given for it wins, and it keeps the
    position of its first appearance. Pure computation: no I/O, no
    environment access.

    Raises ValueError if keys and values differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    result: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        result[k] = v
    return list(result.values())


def test_defaults_when_empty() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["b", "a"], ["2", "1"]) == ["fast", "3", "2", "1"]


def test_extras_mixed_with_known_keys() -> None:
    assert settings(["x", "mode", "y"], ["1", "slow", "2"]) == [
        "slow",
        "3",
        "1",
        "2",
    ]


def test_duplicate_keys_last_value_wins_first_position_kept() -> None:
    assert settings(["x", "y", "x"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_known_key() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_empty_string_values_are_kept() -> None:
    assert settings(["mode", "x"], ["", ""]) == ["", "3", ""]


def test_mismatched_lengths_raise() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])


def test_inputs_not_mutated() -> None:
    keys = ["x", "mode"]
    values = ["1", "slow"]
    settings(keys, values)
    assert keys == ["x", "mode"]
    assert values == ["1", "slow"]

